type ServerInterface interface {
	// Advisor recipes
	// (GET /advisors)
	ListAdvisors(w http.ResponseWriter, r *http.Request)
	// Agents from the policy with their grants
	// (GET /agents)
	ListAgents(w http.ResponseWriter, r *http.Request)
	// Approve an agent for today (humans only). Returns a token valid for 8 h.
	// (POST /agents/{id}/approve)
	ApproveAgent(w http.ResponseWriter, r *http.Request, id AgentId)
	// Revoke the grant of an agent
	// (DELETE /agents/{id}/grant)
	RevokeAgent(w http.ResponseWriter, r *http.Request, id AgentId)
	// Audit trail (agent grants, LLM log deletes, merges, break-glass)
	// (GET /audit)
	ListAudit(w http.ResponseWriter, r *http.Request, params ListAuditParams)
	// Open changes (local worktrees, remote branches, open MRs) and recent merges
	// (GET /changes)
	ListChanges(w http.ResponseWriter, r *http.Request, params ListChangesParams)
	// New change (worktree, branch and metadata file)
	// (POST /changes)
	CreateChange(w http.ResponseWriter, r *http.Request)
	// One change with lifecycle, commits, gates and overlaps
	// (GET /changes/{id})
	GetChange(w http.ResponseWriter, r *http.Request, id ChangeId)
	// Run an advisor recipe on a change
	// (POST /changes/{id}/advisors/{recipe})
	RunAdvisor(w http.ResponseWriter, r *http.Request, id ChangeId, recipe string)
	// Approve the merge request (humans only; agents get 403)
	// (POST /changes/{id}/approve)
	ApproveChange(w http.ResponseWriter, r *http.Request, id ChangeId)
	// Fetch the branch of a change into a local worktree
	// (POST /changes/{id}/checkout)
	CheckoutChange(w http.ResponseWriter, r *http.Request, id ChangeId)
	// Close the change without merge
	// (POST /changes/{id}/close)
	CloseChange(w http.ResponseWriter, r *http.Request, id ChangeId)
	// Suggest a Conventional Commit message from the uncommitted diff and the intent
	// (POST /changes/{id}/commit-message)
	SuggestCommitMessage(w http.ResponseWriter, r *http.Request, id ChangeId)
	// Commits of the change (target..head)
	// (GET /changes/{id}/commits)
	ListCommits(w http.ResponseWriter, r *http.Request, id ChangeId)
	// Commit saved files of the worktree (all changed files, or the given paths)
	// (POST /changes/{id}/commits)
	Commit(w http.ResponseWriter, r *http.Request, id ChangeId)
	// Diff of the change (semantic, source or rendered view)
	// (GET /changes/{id}/diff)
	GetDiff(w http.ResponseWriter, r *http.Request, id ChangeId, params GetDiffParams)
	// Delete a file from the worktree
	// (DELETE /changes/{id}/file)
	DeleteFile(w http.ResponseWriter, r *http.Request, id ChangeId, params DeleteFileParams)
	// Read a file. Secret values are masked.
	// (GET /changes/{id}/file)
	ReadFile(w http.ResponseWriter, r *http.Request, id ChangeId, params ReadFileParams)
	// Save a file to the worktree (full content, or set fields by dotted path). Masked secrets keep their stored value.
	// (PUT /changes/{id}/file)
	WriteFile(w http.ResponseWriter, r *http.Request, id ChangeId, params WriteFileParams)
	// Create a file from a kind skeleton (schema defaults) at the kind's default path
	// (POST /changes/{id}/file/new)
	NewFile(w http.ResponseWriter, r *http.Request, id ChangeId)
	// Policy gates (same evaluation as pk ci)
	// (GET /changes/{id}/gates)
	GetGates(w http.ResponseWriter, r *http.Request, id ChangeId)
	// Render target and change per cluster and compare (grouped by Flux Kustomization)
	// (GET /changes/{id}/impact)
	GetImpact(w http.ResponseWriter, r *http.Request, id ChangeId)
	// Start a change lab on the head of the change
	// (POST /changes/{id}/labs)
	RunLab(w http.ResponseWriter, r *http.Request, id ChangeId)
	// Merge (humans only). 409 "behind main by N, rebase first" when not rebased.
	// (POST /changes/{id}/merge)
	MergeChange(w http.ResponseWriter, r *http.Request, id ChangeId)
	// Schema and cross-file problems of the change worktree
	// (GET /changes/{id}/problems)
	ValidateChange(w http.ResponseWriter, r *http.Request, id ChangeId, params ValidateChangeParams)
	// Push the branch. The first push opens a draft merge request.
	// (POST /changes/{id}/push)
	PushChange(w http.ResponseWriter, r *http.Request, id ChangeId)
	// Move to review (lab gate, metadata to the MR description, remove draft)
	// (POST /changes/{id}/ready)
	MarkReady(w http.ResponseWriter, r *http.Request, id ChangeId)
	// Rebase on the target and force-push with lease. 409 with paths on conflict.
	// (POST /changes/{id}/rebase)
	RebaseChange(w http.ResponseWriter, r *http.Request, id ChangeId)
	// Open a revert change for a merged change (fast path, P2)
	// (POST /changes/{id}/revert)
	RevertChange(w http.ResponseWriter, r *http.Request, id ChangeId)
	// Changed, staged and untracked files of the worktree
	// (GET /changes/{id}/status)
	WorktreeStatus(w http.ResponseWriter, r *http.Request, id ChangeId)
	// Suggested edits (from chat or advisors) in the change
	// (GET /changes/{id}/suggestions)
	ListSuggestions(w http.ResponseWriter, r *http.Request, id ChangeId)
	// File tree of the change worktree with status against the target
	// (GET /changes/{id}/tree)
	GetTree(w http.ResponseWriter, r *http.Request, id ChangeId)
	// Freeform chat as the logged-in human. Edits come back as suggestions.
	// (POST /chat)
	Chat(w http.ResponseWriter, r *http.Request)
	// Clusters with role, ring and applied/verified revision (from Flux)
	// (GET /clusters)
	ListClusters(w http.ResponseWriter, r *http.Request)
	// Approve a change in the forge as another person (PK_DEMO=1 only)
	// (POST /demo/approve)
	DemoApprove(w http.ResponseWriter, r *http.Request)
	// Make fluxsim fail or heal a cluster (PK_DEMO=1 only)
	// (POST /demo/flux)
	DemoFlux(w http.ResponseWriter, r *http.Request)
	// Entities of a kind (or all)
	// (GET /entities)
	ListEntities(w http.ResponseWriter, r *http.Request, params ListEntitiesParams)
	// One entity with fields (truth class, owner, source), references and backlinks
	// (GET /entities/{kind}/{name})
	GetEntity(w http.ResponseWriter, r *http.Request, kind string, name string, params GetEntityParams)
	// The focus of the session (current change, file, object, view)
	// (GET /focus)
	GetFocus(w http.ResponseWriter, r *http.Request)
	// Move the focus. An agent in suggest mode only sends a "look here" card.
	// (PUT /focus)
	SetFocus(w http.ResponseWriter, r *http.Request)
	// Merge commits on main, one row per change (from trailers)
	// (GET /history)
	ListHistory(w http.ResponseWriter, r *http.Request, params ListHistoryParams)
	// One merge commit with trailers, semantic and source diff
	// (GET /history/{sha})
	GetHistoryEntry(w http.ResponseWriter, r *http.Request, sha string)
	// Knowledge base articles
	// (GET /kb)
	ListArticles(w http.ResponseWriter, r *http.Request, params ListArticlesParams)
	// One article with entities and the changes that cite it
	// (GET /kb/article)
	GetArticle(w http.ResponseWriter, r *http.Request, params GetArticleParams)
	// The kind registry
	// (GET /kinds)
	ListKinds(w http.ResponseWriter, r *http.Request)
	// JSON Schema of a kind (with x-pk extensions)
	// (GET /kinds/{kind}/schema)
	GetKindSchema(w http.ResponseWriter, r *http.Request, kind string, params GetKindSchemaParams)
	// Lab definitions (.pk/labs) and recent runs
	// (GET /labs)
	ListLabs(w http.ResponseWriter, r *http.Request, params ListLabsParams)
	// One lab run with its steps
	// (GET /labs/runs/{run})
	GetLabRun(w http.ResponseWriter, r *http.Request, run string)
	// Topology generated from inventory, cabling and .pk/emulation.yaml (read-only)
	// (GET /labs/topology)
	GetTopology(w http.ResponseWriter, r *http.Request, params GetTopologyParams)
	// LLM log entries (platform admins only)
	// (GET /llm/log)
	ListLlmLog(w http.ResponseWriter, r *http.Request, params ListLlmLogParams)
	// Export the LLM log as JSON lines (platform admins only)
	// (GET /llm/log/export)
	ExportLlmLog(w http.ResponseWriter, r *http.Request)
	// Delete an LLM log entry (platform admins only; writes an audit entry)
	// (DELETE /llm/log/{id})
	DeleteLlmLog(w http.ResponseWriter, r *http.Request, id string)
	// Rate an advisor result or chat answer
	// (POST /llm/log/{id}/rating)
	RateLlm(w http.ResponseWriter, r *http.Request, id string)
	// The identity of the caller
	// (GET /me)
	GetMe(w http.ResponseWriter, r *http.Request)
	// The policy on main
	// (GET /policy)
	GetPolicySummary(w http.ResponseWriter, r *http.Request)
	// Forge rules generated from the policy (branch protection, CODEOWNERS preview)
	// (GET /policy/forge-rules)
	GetForgeRules(w http.ResponseWriter, r *http.Request)
	// Rack view (units with occupants; highlights when ref is a change)
	// (GET /racks/{name})
	GetRack(w http.ResponseWriter, r *http.Request, name string, params GetRackParams)
	// A file at a ref (read-only). With convert, old kind versions are converted to the newest.
	// (GET /refs/{ref}/file)
	ReadFileAtRef(w http.ResponseWriter, r *http.Request, ref string, params ReadFileAtRefParams)
	// File tree at a ref (read-only, time travel)
	// (GET /refs/{ref}/tree)
	GetRefTree(w http.ResponseWriter, r *http.Request, ref string)
	// Rollout rings (canary, prod) with their tag, hold and gate (P2)
	// (GET /rings)
	ListRings(w http.ResponseWriter, r *http.Request)
	// Hold a ring tag (stops the rollout to the next rings, P2)
	// (POST /rings/{ring}/hold)
	HoldRing(w http.ResponseWriter, r *http.Request, ring Ring)
	// Move a ring tag forward to a merge commit (P2)
	// (POST /rings/{ring}/promote)
	PromoteRing(w http.ResponseWriter, r *http.Request, ring Ring)
	// Release a held ring tag (P2)
	// (POST /rings/{ring}/release)
	ReleaseRing(w http.ResponseWriter, r *http.Request, ring Ring)
	// Retrieval index search (KB, repo files, trailers, MR discussions, lab reports)
	// (GET /search)
	Search(w http.ResponseWriter, r *http.Request, params SearchParams)
	// Bench status (forge, LLM, Flux, main head) for the top bar
	// (GET /status)
	GetStatus(w http.ResponseWriter, r *http.Request)
	// Accept a suggested edit. It is written to the worktree as a normal edit by the caller.
	// (POST /suggestions/{sid}/accept)
	AcceptSuggestion(w http.ResponseWriter, r *http.Request, sid SuggestionId)
	// Reject a suggested edit
	// (POST /suggestions/{sid}/reject)
	RejectSuggestion(w http.ResponseWriter, r *http.Request, sid SuggestionId)
	// Work items with derived status, and milestones with progress
	// (GET /work)
	GetWorkBoard(w http.ResponseWriter, r *http.Request, params GetWorkBoardParams)
}

