// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// Advisor recipes
	// (GET /advisors)
	ListAdvisors(ctx context.Context, request ListAdvisorsRequestObject) (ListAdvisorsResponseObject, error)
	// Agents from the policy with their grants
	// (GET /agents)
	ListAgents(ctx context.Context, request ListAgentsRequestObject) (ListAgentsResponseObject, error)
	// Approve an agent for today (humans only). Returns a token valid for 8 h.
	// (POST /agents/{id}/approve)
	ApproveAgent(ctx context.Context, request ApproveAgentRequestObject) (ApproveAgentResponseObject, error)
	// Revoke the grant of an agent
	// (DELETE /agents/{id}/grant)
	RevokeAgent(ctx context.Context, request RevokeAgentRequestObject) (RevokeAgentResponseObject, error)
	// Audit trail (agent grants, LLM log deletes, merges, break-glass)
	// (GET /audit)
	ListAudit(ctx context.Context, request ListAuditRequestObject) (ListAuditResponseObject, error)
	// Open changes (local worktrees, remote branches, open MRs) and recent merges
	// (GET /changes)
	ListChanges(ctx context.Context, request ListChangesRequestObject) (ListChangesResponseObject, error)
	// New change (worktree, branch and metadata file)
	// (POST /changes)
	CreateChange(ctx context.Context, request CreateChangeRequestObject) (CreateChangeResponseObject, error)
	// One change with lifecycle, commits, gates and overlaps
	// (GET /changes/{id})
	GetChange(ctx context.Context, request GetChangeRequestObject) (GetChangeResponseObject, error)
	// Run an advisor recipe on a change
	// (POST /changes/{id}/advisors/{recipe})
	RunAdvisor(ctx context.Context, request RunAdvisorRequestObject) (RunAdvisorResponseObject, error)
	// Approve the merge request (humans only; agents get 403)
	// (POST /changes/{id}/approve)
	ApproveChange(ctx context.Context, request ApproveChangeRequestObject) (ApproveChangeResponseObject, error)
	// Fetch the branch of a change into a local worktree
	// (POST /changes/{id}/checkout)
	CheckoutChange(ctx context.Context, request CheckoutChangeRequestObject) (CheckoutChangeResponseObject, error)
	// Close the change without merge
	// (POST /changes/{id}/close)
	CloseChange(ctx context.Context, request CloseChangeRequestObject) (CloseChangeResponseObject, error)
	// Suggest a Conventional Commit message from the uncommitted diff and the intent
	// (POST /changes/{id}/commit-message)
	SuggestCommitMessage(ctx context.Context, request SuggestCommitMessageRequestObject) (SuggestCommitMessageResponseObject, error)
	// Commits of the change (target..head)
	// (GET /changes/{id}/commits)
	ListCommits(ctx context.Context, request ListCommitsRequestObject) (ListCommitsResponseObject, error)
	// Commit saved files of the worktree (all changed files, or the given paths)
	// (POST /changes/{id}/commits)
	Commit(ctx context.Context, request CommitRequestObject) (CommitResponseObject, error)
	// Diff of the change (semantic, source or rendered view)
	// (GET /changes/{id}/diff)
	GetDiff(ctx context.Context, request GetDiffRequestObject) (GetDiffResponseObject, error)
	// Delete a file from the worktree
	// (DELETE /changes/{id}/file)
	DeleteFile(ctx context.Context, request DeleteFileRequestObject) (DeleteFileResponseObject, error)
	// Read a file. Secret values are masked.
	// (GET /changes/{id}/file)
	ReadFile(ctx context.Context, request ReadFileRequestObject) (ReadFileResponseObject, error)
	// Save a file to the worktree (full content, or set fields by dotted path). Masked secrets keep their stored value.
	// (PUT /changes/{id}/file)
	WriteFile(ctx context.Context, request WriteFileRequestObject) (WriteFileResponseObject, error)
	// Create a file from a kind skeleton (schema defaults) at the kind's default path
	// (POST /changes/{id}/file/new)
	NewFile(ctx context.Context, request NewFileRequestObject) (NewFileResponseObject, error)
	// Policy gates (same evaluation as pk ci)
	// (GET /changes/{id}/gates)
	GetGates(ctx context.Context, request GetGatesRequestObject) (GetGatesResponseObject, error)
	// Render target and change per cluster and compare (grouped by Flux Kustomization)
	// (GET /changes/{id}/impact)
	GetImpact(ctx context.Context, request GetImpactRequestObject) (GetImpactResponseObject, error)
	// Start a change lab on the head of the change
	// (POST /changes/{id}/labs)
	RunLab(ctx context.Context, request RunLabRequestObject) (RunLabResponseObject, error)
	// Merge (humans only). 409 "behind main by N, rebase first" when not rebased.
	// (POST /changes/{id}/merge)
	MergeChange(ctx context.Context, request MergeChangeRequestObject) (MergeChangeResponseObject, error)
	// Schema and cross-file problems of the change worktree
	// (GET /changes/{id}/problems)
	ValidateChange(ctx context.Context, request ValidateChangeRequestObject) (ValidateChangeResponseObject, error)
	// Push the branch. The first push opens a draft merge request.
	// (POST /changes/{id}/push)
	PushChange(ctx context.Context, request PushChangeRequestObject) (PushChangeResponseObject, error)
	// Move to review (lab gate, metadata to the MR description, remove draft)
	// (POST /changes/{id}/ready)
	MarkReady(ctx context.Context, request MarkReadyRequestObject) (MarkReadyResponseObject, error)
	// Rebase on the target and force-push with lease. 409 with paths on conflict.
	// (POST /changes/{id}/rebase)
	RebaseChange(ctx context.Context, request RebaseChangeRequestObject) (RebaseChangeResponseObject, error)
	// Open a revert change for a merged change (fast path, P2)
	// (POST /changes/{id}/revert)
	RevertChange(ctx context.Context, request RevertChangeRequestObject) (RevertChangeResponseObject, error)
	// Changed, staged and untracked files of the worktree
	// (GET /changes/{id}/status)
	WorktreeStatus(ctx context.Context, request WorktreeStatusRequestObject) (WorktreeStatusResponseObject, error)
	// Suggested edits (from chat or advisors) in the change
	// (GET /changes/{id}/suggestions)
	ListSuggestions(ctx context.Context, request ListSuggestionsRequestObject) (ListSuggestionsResponseObject, error)
	// File tree of the change worktree with status against the target
	// (GET /changes/{id}/tree)
	GetTree(ctx context.Context, request GetTreeRequestObject) (GetTreeResponseObject, error)
	// Freeform chat as the logged-in human. Edits come back as suggestions.
	// (POST /chat)
	Chat(ctx context.Context, request ChatRequestObject) (ChatResponseObject, error)
	// Clusters with role, ring and applied/verified revision (from Flux)
	// (GET /clusters)
	ListClusters(ctx context.Context, request ListClustersRequestObject) (ListClustersResponseObject, error)
	// Approve a change in the forge as another person (PK_DEMO=1 only)
	// (POST /demo/approve)
	DemoApprove(ctx context.Context, request DemoApproveRequestObject) (DemoApproveResponseObject, error)
	// Make fluxsim fail or heal a cluster (PK_DEMO=1 only)
	// (POST /demo/flux)
	DemoFlux(ctx context.Context, request DemoFluxRequestObject) (DemoFluxResponseObject, error)
	// Entities of a kind (or all)
	// (GET /entities)
	ListEntities(ctx context.Context, request ListEntitiesRequestObject) (ListEntitiesResponseObject, error)
	// One entity with fields (truth class, owner, source), references and backlinks
	// (GET /entities/{kind}/{name})
	GetEntity(ctx context.Context, request GetEntityRequestObject) (GetEntityResponseObject, error)
	// The focus of the session (current change, file, object, view)
	// (GET /focus)
	GetFocus(ctx context.Context, request GetFocusRequestObject) (GetFocusResponseObject, error)
	// Move the focus. An agent in suggest mode only sends a "look here" card.
	// (PUT /focus)
	SetFocus(ctx context.Context, request SetFocusRequestObject) (SetFocusResponseObject, error)
	// Merge commits on main, one row per change (from trailers)
	// (GET /history)
	ListHistory(ctx context.Context, request ListHistoryRequestObject) (ListHistoryResponseObject, error)
	// One merge commit with trailers, semantic and source diff
	// (GET /history/{sha})
	GetHistoryEntry(ctx context.Context, request GetHistoryEntryRequestObject) (GetHistoryEntryResponseObject, error)
	// Knowledge base articles
	// (GET /kb)
	ListArticles(ctx context.Context, request ListArticlesRequestObject) (ListArticlesResponseObject, error)
	// One article with entities and the changes that cite it
	// (GET /kb/article)
	GetArticle(ctx context.Context, request GetArticleRequestObject) (GetArticleResponseObject, error)
	// The kind registry
	// (GET /kinds)
	ListKinds(ctx context.Context, request ListKindsRequestObject) (ListKindsResponseObject, error)
	// JSON Schema of a kind (with x-pk extensions)
	// (GET /kinds/{kind}/schema)
	GetKindSchema(ctx context.Context, request GetKindSchemaRequestObject) (GetKindSchemaResponseObject, error)
	// Lab definitions (.pk/labs) and recent runs
	// (GET /labs)
	ListLabs(ctx context.Context, request ListLabsRequestObject) (ListLabsResponseObject, error)
	// One lab run with its steps
	// (GET /labs/runs/{run})
	GetLabRun(ctx context.Context, request GetLabRunRequestObject) (GetLabRunResponseObject, error)
	// Topology generated from inventory, cabling and .pk/emulation.yaml (read-only)
	// (GET /labs/topology)
	GetTopology(ctx context.Context, request GetTopologyRequestObject) (GetTopologyResponseObject, error)
	// LLM log entries (platform admins only)
	// (GET /llm/log)
	ListLlmLog(ctx context.Context, request ListLlmLogRequestObject) (ListLlmLogResponseObject, error)
	// Export the LLM log as JSON lines (platform admins only)
	// (GET /llm/log/export)
	ExportLlmLog(ctx context.Context, request ExportLlmLogRequestObject) (ExportLlmLogResponseObject, error)
	// Delete an LLM log entry (platform admins only; writes an audit entry)
	// (DELETE /llm/log/{id})
	DeleteLlmLog(ctx context.Context, request DeleteLlmLogRequestObject) (DeleteLlmLogResponseObject, error)
	// Rate an advisor result or chat answer
	// (POST /llm/log/{id}/rating)
	RateLlm(ctx context.Context, request RateLlmRequestObject) (RateLlmResponseObject, error)
	// The identity of the caller
	// (GET /me)
	GetMe(ctx context.Context, request GetMeRequestObject) (GetMeResponseObject, error)
	// The policy on main
	// (GET /policy)
	GetPolicySummary(ctx context.Context, request GetPolicySummaryRequestObject) (GetPolicySummaryResponseObject, error)
	// Forge rules generated from the policy (branch protection, CODEOWNERS preview)
	// (GET /policy/forge-rules)
	GetForgeRules(ctx context.Context, request GetForgeRulesRequestObject) (GetForgeRulesResponseObject, error)
	// Rack view (units with occupants; highlights when ref is a change)
	// (GET /racks/{name})
	GetRack(ctx context.Context, request GetRackRequestObject) (GetRackResponseObject, error)
	// A file at a ref (read-only). With convert, old kind versions are converted to the newest.
	// (GET /refs/{ref}/file)
	ReadFileAtRef(ctx context.Context, request ReadFileAtRefRequestObject) (ReadFileAtRefResponseObject, error)
	// File tree at a ref (read-only, time travel)
	// (GET /refs/{ref}/tree)
	GetRefTree(ctx context.Context, request GetRefTreeRequestObject) (GetRefTreeResponseObject, error)
	// Rollout rings (canary, prod) with their tag, hold and gate (P2)
	// (GET /rings)
	ListRings(ctx context.Context, request ListRingsRequestObject) (ListRingsResponseObject, error)
	// Hold a ring tag (stops the rollout to the next rings, P2)
	// (POST /rings/{ring}/hold)
	HoldRing(ctx context.Context, request HoldRingRequestObject) (HoldRingResponseObject, error)
	// Move a ring tag forward to a merge commit (P2)
	// (POST /rings/{ring}/promote)
	PromoteRing(ctx context.Context, request PromoteRingRequestObject) (PromoteRingResponseObject, error)
	// Release a held ring tag (P2)
	// (POST /rings/{ring}/release)
	ReleaseRing(ctx context.Context, request ReleaseRingRequestObject) (ReleaseRingResponseObject, error)
	// Retrieval index search (KB, repo files, trailers, MR discussions, lab reports)
	// (GET /search)
	Search(ctx context.Context, request SearchRequestObject) (SearchResponseObject, error)
	// Bench status (forge, LLM, Flux, main head) for the top bar
	// (GET /status)
	GetStatus(ctx context.Context, request GetStatusRequestObject) (GetStatusResponseObject, error)
	// Accept a suggested edit. It is written to the worktree as a normal edit by the caller.
	// (POST /suggestions/{sid}/accept)
	AcceptSuggestion(ctx context.Context, request AcceptSuggestionRequestObject) (AcceptSuggestionResponseObject, error)
	// Reject a suggested edit
	// (POST /suggestions/{sid}/reject)
	RejectSuggestion(ctx context.Context, request RejectSuggestionRequestObject) (RejectSuggestionResponseObject, error)
	// Work items with derived status, and milestones with progress
	// (GET /work)
	GetWorkBoard(ctx context.Context, request GetWorkBoardRequestObject) (GetWorkBoardResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// ListAdvisors operation middleware
func (sh *strictHandler) ListAdvisors(w http.ResponseWriter, r *http.Request) {
	var request ListAdvisorsRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.ListAdvisors(ctx, request.(ListAdvisorsRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ListAdvisors")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(ListAdvisorsResponseObject); ok {
		if err := validResponse.VisitListAdvisorsResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

